<?php include '../includes/header.php';$u=user();if(is_admin()){$r=mysqli_query($conn,"SELECT f.*,u.name owner_name FROM user_files f JOIN users u ON u.id=f.owner_id ORDER BY f.id DESC");}else{$s=mysqli_prepare($conn,"SELECT f.*,u.name owner_name FROM user_files f JOIN users u ON u.id=f.owner_id WHERE f.owner_id=? OR (f.institution_type=? AND f.institution_code=?) ORDER BY f.id DESC");mysqli_stmt_bind_param($s,'iss',$u['id'],$u['institution_type'],$u['institution_code']);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);} ?><h1>Files</h1><div class="card"><form method="post" enctype="multipart/form-data" action="upload.php"><?=csrf_field()?><input type="file" name="file" required><input name="description" placeholder="Description"><button>Upload</button></form></div><div class="card"><table><tr><th>File</th><th>Category</th><th>Size</th><th>Owner</th><th>Date</th></tr><?php while($x=mysqli_fetch_assoc($r)):?><tr><td><a href="download.php?id=<?=$x['id']?>"><?=e($x['original_name'])?></a></td><td><?=e($x['category'])?></td><td><?=number_format($x['size'])?></td><td><?=e($x['owner_name'])?></td><td><?=e($x['created_at'])?></td></tr><?php endwhile;?></table></div><?php include '../includes/footer.php';
